INSERT INTO client_releases (version, version_key, platform, file_key, file_name, size, sha256, notes, published_at) VALUES ('2.76.0', 2076000, 'windows', 'releases/CosmicPlatformer-Setup-2.76.0.exe', 'CosmicPlatformer-Setup-2.76.0.exe', 151702596, '1cef77c0eda26099dfbdccbc7b4aa6518b79e3f7c79c0b5b8a8927697833c568', 'Version 2.76.0 :
• Boss : chaque boss est découpé en parties qui suivent son dessin image par image (tête, cou, corps, ailes, queue, pattes, griffes, souffle pour Pyrrhax ; le corps pour les autres), au lieu d''une seule boîte. Les formes sont tirées des sprites de ses 94 feuilles par un outil, au pixel près.
• Pyrrhax se bat par parties : sa tête est un point faible (× 2), sa queue est blindée (× 0,5), son cou, son corps, ses ailes et ses pattes prennent les coups normalement. Vous pouvez le toucher au bout d''une aile, bien au-delà de son ancienne boîte. Seules ses griffes, son souffle et sa tête pendant la morsure blessent au contact. Les replays d''avant rejouent à l''identique et aucun record n''est effacé.
• Fiches des boss : nouvel onglet « Où frapper » (STATISTIQUES › un boss). Il montre le vrai sprite avec une puce par phase et une puce par pose (repos, élan, attaque…), ses parties sur l''image en cours, et une légende avec le rôle et les dégâts de chaque partie. Les fiches des Gigaboss d''Asterion montrent aussi leurs parties.
• Ennemis qui fuient : un ennemi affaibli ne s''éloigne plus qu''à 5,5 tuiles au plus d''où il a commencé à fuir, et un ennemi volant ne monte plus qu''à 2 tuiles au-dessus. Arrivé à la limite, il est acculé : il vous fait face, attaque ou pare s''il le peut, et se laisse toucher. Les fantômes ne finissent plus au plafond ni hors de l''écran. Éditeur d''ennemis : « Distance de fuite max ».', '2026-11-19T17:23:25.887Z') ON CONFLICT (version) DO NOTHING;
